// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import "../sale/Sale.sol";
import "./CiretaFractionFactory.sol";
import "./IssuerRegistry.sol";
import "./PlatformFeeManager.sol";

/**
 * @title CiretaSaleFactory
 * @dev Platform-level factory for deploying Sale contracts per token.
 *      Active issuers (registered in IssuerRegistry) deploy their own sales.
 *      Platform admin (owner) retains oversight via Sale.admin role.
 *      Fees are enforced on-chain via PlatformFeeManager verification.
 */
contract CiretaSaleFactory is Initializable, OwnableUpgradeable, UUPSUpgradeable {
    address public saleImplementation;
    CiretaFractionFactory public fractionFactory;

    mapping(address => address[]) public tokenSales;
    address[] public allSales;

    // Issuer-centric deployment
    IssuerRegistry public issuerRegistry;
    PlatformFeeManager public platformFeeManager;
    mapping(address => address[]) public issuerSales;

    /// @dev Reserved storage gap for future upgrades
    uint256[47] private __gap;

    event SaleDeployed(
        address indexed token,
        address indexed sale,
        address indexed issuer
    );
    event IssuerRegistrySet(address indexed registry);
    event PlatformFeeManagerSet(address indexed feeManager);

    error NotActiveIssuer();
    error FeeMismatch();
    error IssuerMismatch();
    error FactoryMismatch();

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(
        address initialOwner,
        address _saleImplementation
    ) public initializer {
        __Ownable_init(initialOwner);
        saleImplementation = _saleImplementation;
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    // ── Configuration (admin-only) ──────────────────────────────────────────

    function setSaleImplementation(address impl) external onlyOwner {
        require(impl != address(0), "zero impl");
        saleImplementation = impl;
    }

    function setFractionFactory(address _fractionFactory) external onlyOwner {
        require(_fractionFactory != address(0), "zero addr");
        fractionFactory = CiretaFractionFactory(_fractionFactory);
    }

    function setIssuerRegistry(address _registry) external onlyOwner {
        require(_registry != address(0), "zero addr");
        issuerRegistry = IssuerRegistry(_registry);
        emit IssuerRegistrySet(_registry);
    }

    function setPlatformFeeManager(address _feeManager) external onlyOwner {
        require(_feeManager != address(0), "zero addr");
        platformFeeManager = PlatformFeeManager(_feeManager);
        emit PlatformFeeManagerSet(_feeManager);
    }

    // ── Modifiers ───────────────────────────────────────────────────────────

    modifier onlyActiveIssuer() {
        if (address(issuerRegistry) == address(0) || !issuerRegistry.isActiveIssuer(msg.sender)) {
            revert NotActiveIssuer();
        }
        _;
    }

    // ── Sale Deployment (issuer-initiated) ──────────────────────────────────

    /**
     * @dev Deploy a new Direct-mode Sale proxy.
     *      Called by active issuers. initData must encode Sale.initialize()
     *      with issuer=msg.sender, factory=address(this), and correct fee.
     *      Factory verifies these after deployment.
     */
    function deploySale(
        address token,
        bytes calldata initData
    ) external onlyActiveIssuer returns (address sale) {
        require(saleImplementation != address(0), "no impl");
        require(token != address(0), "zero token");

        ERC1967Proxy proxy = new ERC1967Proxy(saleImplementation, initData);
        sale = address(proxy);

        _verifySale(sale);

        tokenSales[token].push(sale);
        allSales.push(sale);
        issuerSales[msg.sender].push(sale);

        emit SaleDeployed(token, sale, msg.sender);
    }

    /**
     * @dev Deploy a new Vested-mode Sale proxy with vault + fraction token.
     *      Called by active issuers. initData must encode Sale.initialize()
     *      with factory=address(this). Factory calls setVestedMode() which
     *      passes adminOnly because _isAdmin() treats the factory as admin.
     */
    function deploySaleVested(
        address token,
        bytes calldata initData,
        string memory fractionName,
        string memory fractionSymbol,
        uint8 fractionDecimals,
        address identityRegistry,
        uint256 cliffDuration,
        uint256 vestingDuration,
        CiretaVault.ExcessPolicy excessPolicy
    ) external onlyActiveIssuer returns (address sale, address vaultAddr, address fractionAddr) {
        require(saleImplementation != address(0), "no impl");
        require(address(fractionFactory) != address(0), "no fraction factory");
        require(token != address(0), "zero token");

        // Deploy Sale proxy — factory=address(this) in initData
        ERC1967Proxy proxy = new ERC1967Proxy(saleImplementation, initData);
        sale = address(proxy);

        // Verify issuer, factory, and fee
        _verifySale(sale);

        // Deploy vault + fraction via CiretaFractionFactory
        (fractionAddr, vaultAddr) = fractionFactory.deployVaultAndFraction(
            fractionName, fractionSymbol, fractionDecimals,
            token, identityRegistry, sale,
            cliffDuration, vestingDuration, excessPolicy, owner()
        );

        // Configure vested mode — factory is recognized as admin via _isAdmin()
        Sale(sale).setVestedMode(vaultAddr, fractionAddr);

        tokenSales[token].push(sale);
        allSales.push(sale);
        issuerSales[msg.sender].push(sale);

        emit SaleDeployed(token, sale, msg.sender);
    }

    // ── Internal Verification ───────────────────────────────────────────────

    /// @dev Verify deployed Sale has correct issuer, factory, and fee.
    function _verifySale(address sale) internal view {
        Sale saleContract = Sale(sale);

        // Issuer must be the caller
        if (saleContract.issuer() != msg.sender) revert IssuerMismatch();

        // Factory must be this contract (admin is resolved via factory.owner())
        if (saleContract.factory() != address(this)) revert FactoryMismatch();

        // Fee must match PlatformFeeManager
        if (address(platformFeeManager) != address(0)) {
            uint256 expectedFee = platformFeeManager.getFeeForIssuer(msg.sender);
            if (saleContract.feeBasisPoints() != expectedFee) revert FeeMismatch();
        }
    }

    // ── View ────────────────────────────────────────────────────────────────

    function getSalesForToken(address token) external view returns (address[] memory) {
        return tokenSales[token];
    }

    function getSalesForIssuer(address issuerAddr) external view returns (address[] memory) {
        return issuerSales[issuerAddr];
    }

    function totalSales() external view returns (uint256) {
        return allSales.length;
    }
}

src/platform/CiretaTokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import "../token/CiretaToken.sol";
import "../token/IdentityRegistry.sol";
import "../token/ModularCompliance.sol";
import "./IssuerRegistry.sol";

/**
 * @title CiretaTokenFactory
 * @dev Factory for deploying ERC-3643 compliant tokens.
 *      Canonical token implementation: ../token/CiretaToken.sol
 *      Canonical identity registry: ../token/IdentityRegistry.sol
 *      Canonical compliance: ../token/ModularCompliance.sol
 */
contract CiretaTokenFactory is
    Initializable,
    OwnableUpgradeable,
    UUPSUpgradeable
{
    // Implementation contracts
    address public tokenImplementation;
    address public identityRegistryImplementation;
    address public complianceImplementation;

    // Platform registries (shared)
    address public claimTopicsRegistry;
    address public trustedIssuersRegistry;
    address public identityRegistryStorage;
    address public issuerRegistry;

    // Deployed tokens
    address[] public deployedTokens;
    mapping(address => bool) public isDeployedToken;

    /// @dev When true, uses SimpleIdentityRegistry (whitelist mode).
    ///      When false, uses full IdentityRegistry (ERC-3643 ONCHAINID mode).
    bool public simpleIdentityMode;

    /// @dev Reserved storage gap for future upgrades
    uint256[50] private __gap;

    // Events
    event TokenDeployed(
        address indexed token,
        address indexed identityRegistry,
        address indexed compliance,
        string name,
        string symbol,
        address issuer
    );
    event ImplementationsUpdated(
        address token,
        address identityRegistry,
        address compliance
    );
    event IdentityModeChanged(bool simpleMode);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address initialOwner,
        address _tokenImpl,
        address _identityRegistryImpl,
        address _complianceImpl,
        address _claimTopicsRegistry,
        address _trustedIssuersRegistry,
        address _identityRegistryStorage,
        address _issuerRegistry
    ) public initializer {
        __Ownable_init(initialOwner);

        tokenImplementation = _tokenImpl;
        identityRegistryImplementation = _identityRegistryImpl;
        complianceImplementation = _complianceImpl;
        claimTopicsRegistry = _claimTopicsRegistry;
        trustedIssuersRegistry = _trustedIssuersRegistry;
        identityRegistryStorage = _identityRegistryStorage;
        issuerRegistry = _issuerRegistry;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    /**
     * @dev Toggle between simple whitelist mode and full ERC-3643 ONCHAINID mode.
     *      Only affects NEW token deployments — existing tokens keep their registry.
     */
    function setSimpleIdentityMode(bool _simpleMode) external onlyOwner {
        simpleIdentityMode = _simpleMode;
        emit IdentityModeChanged(_simpleMode);
    }

    function updateImplementations(
        address _tokenImpl,
        address _identityRegistryImpl,
        address _complianceImpl
    ) external onlyOwner {
        if (_tokenImpl != address(0)) {
            tokenImplementation = _tokenImpl;
        }
        if (_identityRegistryImpl != address(0)) {
            identityRegistryImplementation = _identityRegistryImpl;
        }
        if (_complianceImpl != address(0)) {
            complianceImplementation = _complianceImpl;
        }

        emit ImplementationsUpdated(
            tokenImplementation,
            identityRegistryImplementation,
            complianceImplementation
        );
    }

    function deployToken(
        string calldata name,
        string calldata symbol,
        uint8 decimals,
        address issuer
    ) external returns (
        address tokenProxy,
        address identityRegistryProxy,
        address complianceProxy
    ) {
        require(issuer != address(0), "zero issuer");

        // Allow owner (admin) or active issuers to deploy
        // Issuers must deploy for themselves (issuer == msg.sender)
        if (msg.sender != owner()) {
            require(
                issuerRegistry != address(0) &&
                IssuerRegistry(issuerRegistry).isActiveIssuer(msg.sender),
                "not owner or active issuer"
            );
            require(msg.sender == issuer, "issuer must be msg.sender");
        }

        // Deploy Identity Registry (same initialize signature for both implementations)
        bytes memory irInitData = abi.encodeWithSelector(
            IdentityRegistry.initialize.selector,
            issuer,
            claimTopicsRegistry,
            trustedIssuersRegistry,
            identityRegistryStorage
        );
        identityRegistryProxy = address(
            new ERC1967Proxy(identityRegistryImplementation, irInitData)
        );

        // Deploy Compliance — initialize with factory as temporary owner so we can call bindToken()
        bytes memory compInitData = abi.encodeWithSelector(
            ModularCompliance.initialize.selector,
            address(this)
        );
        complianceProxy = address(
            new ERC1967Proxy(complianceImplementation, compInitData)
        );

        // Deploy Token — issuer gets all roles, platform admin gets oversight roles (not SUPPLY_ROLE)
        bytes memory tokenInitData = abi.encodeWithSelector(
            CiretaToken.initialize.selector,
            name,
            symbol,
            decimals,
            identityRegistryProxy,
            complianceProxy,
            issuer,
            owner()
        );
        tokenProxy = address(
            new ERC1967Proxy(tokenImplementation, tokenInitData)
        );

        // Bind token to compliance (factory is owner, so this succeeds)
        ModularCompliance(complianceProxy).bindToken(tokenProxy);

        // Transfer compliance ownership to the issuer
        ModularCompliance(complianceProxy).transferOwnership(issuer);

        // Bind identity registry to shared storage (only in full ERC-3643 mode)
        if (!simpleIdentityMode) {
            IIdentityRegistryStorage(identityRegistryStorage).bindIdentityRegistry(
                identityRegistryProxy
            );
        }

        // Track deployment
        deployedTokens.push(tokenProxy);
        isDeployedToken[tokenProxy] = true;

        emit TokenDeployed(
            tokenProxy,
            identityRegistryProxy,
            complianceProxy,
            name,
            symbol,
            issuer
        );

        return (tokenProxy, identityRegistryProxy, complianceProxy);
    }

    function getDeployedTokensCount() external view returns (uint256) {
        return deployedTokens.length;
    }

    function getDeployedTokens(
        uint256 offset,
        uint256 limit
    ) external view returns (address[] memory) {
        uint256 total = deployedTokens.length;
        if (offset >= total) {
            return new address[](0);
        }

        uint256 end = offset + limit;
        if (end > total) {
            end = total;
        }

        address[] memory result = new address[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            result[i - offset] = deployedTokens[i];
        }

        return result;
    }
}

src/platform/ClaimTopicsRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "../interfaces/IClaimTopicsRegistry.sol";

/**
 * @title ClaimTopicsRegistry
 * @dev Registry of claim topics required for investor verification
 */
contract ClaimTopicsRegistry is
    Initializable,
    OwnableUpgradeable,
    UUPSUpgradeable,
    IClaimTopicsRegistry
{
    // Standard claim topics
    uint256 public constant CLAIM_TOPIC_KYC = 1;
    uint256 public constant CLAIM_TOPIC_AML = 2;
    uint256 public constant CLAIM_TOPIC_ACCREDITED_INVESTOR = 3;
    uint256 public constant CLAIM_TOPIC_JURISDICTION = 4;

    // Array of required claim topics
    uint256[] private _claimTopics;

    // Mapping topic => exists
    mapping(uint256 => bool) private _claimTopicExists;

    /// @dev Reserved storage gap for future upgrades
    uint256[50] private __gap;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner) public initializer {
        __Ownable_init(initialOwner);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    function addClaimTopic(uint256 claimTopic) external override onlyOwner {
        require(claimTopic > 0, "invalid topic");
        require(!_claimTopicExists[claimTopic], "topic exists");

        _claimTopics.push(claimTopic);
        _claimTopicExists[claimTopic] = true;

        emit ClaimTopicAdded(claimTopic);
    }

    function removeClaimTopic(uint256 claimTopic) external override onlyOwner {
        require(_claimTopicExists[claimTopic], "topic not found");

        _claimTopicExists[claimTopic] = false;

        // Remove from array
        uint256 length = _claimTopics.length;
        for (uint256 i = 0; i < length; i++) {
            if (_claimTopics[i] == claimTopic) {
                _claimTopics[i] = _claimTopics[length - 1];
                _claimTopics.pop();
                break;
            }
        }

        emit ClaimTopicRemoved(claimTopic);
    }

    function getClaimTopics() external view override returns (uint256[] memory) {
        return _claimTopics;
    }
}

src/platform/IdentityRegistryStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "../interfaces/IIdentityRegistryStorage.sol";

/**
 * @title IdentityRegistryStorage
 * @dev Storage contract for identity data, shared across multiple Identity Registries
 */
contract IdentityRegistryStorage is
    Initializable,
    OwnableUpgradeable,
    UUPSUpgradeable,
    IIdentityRegistryStorage
{
    // Mapping of investor address to identity contract
    mapping(address => IIdentity) private _identities;

    // Mapping of investor address to country code
    mapping(address => uint16) private _countries;

    // Array of linked identity registries
    address[] private _identityRegistries;

    // Mapping to check if an identity registry is linked
    mapping(address => bool) private _identityRegistryLinked;

    /// @dev Reserved storage gap for future upgrades
    uint256[50] private __gap;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner) public initializer {
        __Ownable_init(initialOwner);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    modifier onlyLinkedRegistry() {
        require(
            _identityRegistryLinked[msg.sender],
            "caller not linked registry"
        );
        _;
    }

    function addIdentityToStorage(
        address userAddress,
        IIdentity identity,
        uint16 country
    ) external override onlyLinkedRegistry {
        require(userAddress != address(0), "zero address");
        require(address(identity) != address(0), "zero identity");
        require(address(_identities[userAddress]) == address(0), "already stored");

        _identities[userAddress] = identity;
        _countries[userAddress] = country;

        emit IdentityStored(userAddress, identity);
    }

    function removeIdentityFromStorage(
        address userAddress
    ) external override onlyLinkedRegistry {
        require(address(_identities[userAddress]) != address(0), "not stored");

        IIdentity identity = _identities[userAddress];
        delete _identities[userAddress];
        delete _countries[userAddress];

        emit IdentityUnstored(userAddress, identity);
    }

    function modifyStoredIdentity(
        address userAddress,
        IIdentity identity
    ) external override onlyLinkedRegistry {
        require(address(_identities[userAddress]) != address(0), "not stored");
        require(address(identity) != address(0), "zero identity");

        IIdentity oldIdentity = _identities[userAddress];
        _identities[userAddress] = identity;

        emit IdentityModified(userAddress, oldIdentity, identity);
    }

    function modifyStoredInvestorCountry(
        address userAddress,
        uint16 country
    ) external override onlyLinkedRegistry {
        require(address(_identities[userAddress]) != address(0), "not stored");

        _countries[userAddress] = country;

        emit CountryModified(userAddress, country);
    }

    function bindIdentityRegistry(
        address identityRegistry
    ) external override onlyOwner {
        require(identityRegistry != address(0), "zero address");
        require(!_identityRegistryLinked[identityRegistry], "already bound");

        _identityRegistries.push(identityRegistry);
        _identityRegistryLinked[identityRegistry] = true;

        emit IdentityRegistryBound(identityRegistry);
    }

    function unbindIdentityRegistry(
        address identityRegistry
    ) external override onlyOwner {
        require(_identityRegistryLinked[identityRegistry], "not bound");

        _identityRegistryLinked[identityRegistry] = false;

        // Remove from array
        uint256 length = _identityRegistries.length;
        for (uint256 i = 0; i < length; i++) {
            if (_identityRegistries[i] == identityRegistry) {
                _identityRegistries[i] = _identityRegistries[length - 1];
                _identityRegistries.pop();
                break;
            }
        }

        emit IdentityRegistryUnbound(identityRegistry);
    }

    function linkedIdentityRegistries()
        external
        view
        override
        returns (address[] memory)
    {
        return _identityRegistries;
    }

    function storedIdentity(
        address userAddress
    ) external view override returns (IIdentity) {
        return _identities[userAddress];
    }

    function storedInvestorCountry(
        address userAddress
    ) external view override returns (uint16) {
        return _countries[userAddress];
    }
}

