// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

/**
 * @title IssuerRegistry
 * @dev Registry of approved issuers on the platform
 */
contract IssuerRegistry is
    Initializable,
    OwnableUpgradeable,
    UUPSUpgradeable
{
    enum IssuerStatus {
        None,
        Pending,
        Active,
        Suspended
    }

    struct Issuer {
        address wallet;
        string name;
        string jurisdiction;
        IssuerStatus status;
        uint256 registeredAt;
        uint256 updatedAt;
    }

    // Mapping issuer wallet => issuer data
    mapping(address => Issuer) public issuers;

    // Array of all issuer addresses
    address[] private _issuerAddresses;

    /// @dev Reserved storage gap for future upgrades
    uint256[50] private __gap;

    // Events
    event IssuerRegistered(address indexed wallet, string name, string jurisdiction);
    event IssuerActivated(address indexed wallet);
    event IssuerSuspended(address indexed wallet, string reason);
    event IssuerUpdated(address indexed wallet, string name, string jurisdiction);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner) public initializer {
        __Ownable_init(initialOwner);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    modifier onlyActiveIssuer() {
        require(issuers[msg.sender].status == IssuerStatus.Active, "not active issuer");
        _;
    }

    function registerIssuer(
        address wallet,
        string calldata name,
        string calldata jurisdiction
    ) external onlyOwner {
        require(wallet != address(0), "zero address");
        require(bytes(name).length > 0, "empty name");
        require(issuers[wallet].status == IssuerStatus.None, "already registered");

        issuers[wallet] = Issuer({
            wallet: wallet,
            name: name,
            jurisdiction: jurisdiction,
            status: IssuerStatus.Pending,
            registeredAt: block.timestamp,
            updatedAt: block.timestamp
        });

        _issuerAddresses.push(wallet);

        emit IssuerRegistered(wallet, name, jurisdiction);
    }

    function activateIssuer(address wallet) external onlyOwner {
        require(issuers[wallet].status == IssuerStatus.Pending, "not pending");

        issuers[wallet].status = IssuerStatus.Active;
        issuers[wallet].updatedAt = block.timestamp;

        emit IssuerActivated(wallet);
    }

    function suspendIssuer(
        address wallet,
        string calldata reason
    ) external onlyOwner {
        require(
            issuers[wallet].status == IssuerStatus.Active ||
            issuers[wallet].status == IssuerStatus.Pending,
            "invalid status"
        );

        issuers[wallet].status = IssuerStatus.Suspended;
        issuers[wallet].updatedAt = block.timestamp;

        emit IssuerSuspended(wallet, reason);
    }

    function reactivateIssuer(address wallet) external onlyOwner {
        require(issuers[wallet].status == IssuerStatus.Suspended, "not suspended");

        issuers[wallet].status = IssuerStatus.Active;
        issuers[wallet].updatedAt = block.timestamp;

        emit IssuerActivated(wallet);
    }

    function updateIssuer(
        address wallet,
        string calldata name,
        string calldata jurisdiction
    ) external onlyOwner {
        require(issuers[wallet].status != IssuerStatus.None, "not registered");
        require(bytes(name).length > 0, "empty name");

        issuers[wallet].name = name;
        issuers[wallet].jurisdiction = jurisdiction;
        issuers[wallet].updatedAt = block.timestamp;

        emit IssuerUpdated(wallet, name, jurisdiction);
    }

    function isActiveIssuer(address wallet) external view returns (bool) {
        return issuers[wallet].status == IssuerStatus.Active;
    }

    function getIssuer(address wallet) external view returns (Issuer memory) {
        return issuers[wallet];
    }

    function getAllIssuers() external view returns (address[] memory) {
        return _issuerAddresses;
    }

    function getActiveIssuers() external view returns (address[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < _issuerAddresses.length; i++) {
            if (issuers[_issuerAddresses[i]].status == IssuerStatus.Active) {
                count++;
            }
        }

        address[] memory active = new address[](count);
        uint256 index = 0;
        for (uint256 i = 0; i < _issuerAddresses.length; i++) {
            if (issuers[_issuerAddresses[i]].status == IssuerStatus.Active) {
                active[index] = _issuerAddresses[i];
                index++;
            }
        }

        return active;
    }
}

src/platform/PlatformFeeManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title PlatformFeeManager
 * @dev Manages platform fees for Cireta
 */
contract PlatformFeeManager is
    Initializable,
    OwnableUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    // Platform fee receiver
    address public feeReceiver;

    // Default platform fee in basis points (200 = 2%)
    uint256 public defaultFeeBps;

    // Issuer-specific fee overrides (issuer => fee bps)
    mapping(address => uint256) public issuerFeeBps;

    // Whether issuer has custom fee
    mapping(address => bool) public hasCustomFee;

    // Maximum fee (10%)
    uint256 public constant MAX_FEE_BPS = 1000;

    /// @dev Reserved storage gap for future upgrades
    uint256[50] private __gap;

    // Events
    event FeeReceiverUpdated(address indexed oldReceiver, address indexed newReceiver);
    event DefaultFeeUpdated(uint256 oldFee, uint256 newFee);
    event IssuerFeeUpdated(address indexed issuer, uint256 feeBps);
    event FeeCollected(
        address indexed sale,
        address indexed issuer,
        address indexed token,
        uint256 amount,
        uint256 feeBps
    );

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address initialOwner,
        address _feeReceiver,
        uint256 _defaultFeeBps
    ) public initializer {
        require(_feeReceiver != address(0), "zero fee receiver");
        require(_defaultFeeBps <= MAX_FEE_BPS, "fee too high");

        __Ownable_init(initialOwner);

        feeReceiver = _feeReceiver;
        defaultFeeBps = _defaultFeeBps;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    function setFeeReceiver(address newReceiver) external onlyOwner {
        require(newReceiver != address(0), "zero address");

        address oldReceiver = feeReceiver;
        feeReceiver = newReceiver;

        emit FeeReceiverUpdated(oldReceiver, newReceiver);
    }

    function setDefaultFee(uint256 newFeeBps) external onlyOwner {
        require(newFeeBps <= MAX_FEE_BPS, "fee too high");

        uint256 oldFee = defaultFeeBps;
        defaultFeeBps = newFeeBps;

        emit DefaultFeeUpdated(oldFee, newFeeBps);
    }

    function setIssuerFee(address issuer, uint256 feeBps) external onlyOwner {
        require(feeBps <= MAX_FEE_BPS, "fee too high");

        issuerFeeBps[issuer] = feeBps;
        hasCustomFee[issuer] = true;

        emit IssuerFeeUpdated(issuer, feeBps);
    }

    function removeIssuerCustomFee(address issuer) external onlyOwner {
        delete issuerFeeBps[issuer];
        delete hasCustomFee[issuer];

        emit IssuerFeeUpdated(issuer, defaultFeeBps);
    }

    function getFeeForIssuer(address issuer) external view returns (uint256) {
        if (hasCustomFee[issuer]) {
            return issuerFeeBps[issuer];
        }
        return defaultFeeBps;
    }

    function calculateFee(
        address issuer,
        uint256 amount
    ) external view returns (uint256) {
        uint256 feeBps = hasCustomFee[issuer] ? issuerFeeBps[issuer] : defaultFeeBps;
        return (amount * feeBps) / 10000;
    }

    function collectFee(
        address issuer,
        address token,
        uint256 amount
    ) external returns (uint256 feeAmount) {
        uint256 feeBps = hasCustomFee[issuer] ? issuerFeeBps[issuer] : defaultFeeBps;
        feeAmount = (amount * feeBps) / 10000;

        if (feeAmount > 0) {
            IERC20(token).safeTransferFrom(msg.sender, feeReceiver, feeAmount);

            emit FeeCollected(msg.sender, issuer, token, feeAmount, feeBps);
        }

        return feeAmount;
    }
}

src/platform/TrustedIssuersRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "../interfaces/ITrustedIssuersRegistry.sol";

/**
 * @title TrustedIssuersRegistry
 * @dev Registry of trusted claim issuers for identity verification
 */
contract TrustedIssuersRegistry is
    Initializable,
    OwnableUpgradeable,
    UUPSUpgradeable,
    ITrustedIssuersRegistry
{
    // Array of trusted issuers
    IClaimIssuer[] private _trustedIssuers;

    // Mapping issuer => is trusted
    mapping(address => bool) private _isTrustedIssuer;

    // Mapping issuer => claim topics they can issue
    mapping(address => uint256[]) private _issuerClaimTopics;

    // Mapping issuer => topic => can issue
    mapping(address => mapping(uint256 => bool)) private _hasClaimTopic;

    /// @dev Reserved storage gap for future upgrades
    uint256[50] private __gap;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner) public initializer {
        __Ownable_init(initialOwner);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    function addTrustedIssuer(
        IClaimIssuer trustedIssuer,
        uint256[] calldata claimTopics
    ) external override onlyOwner {
        require(address(trustedIssuer) != address(0), "zero address");
        require(!_isTrustedIssuer[address(trustedIssuer)], "already trusted");
        require(claimTopics.length > 0, "no claim topics");

        _trustedIssuers.push(trustedIssuer);
        _isTrustedIssuer[address(trustedIssuer)] = true;
        _issuerClaimTopics[address(trustedIssuer)] = claimTopics;

        for (uint256 i = 0; i < claimTopics.length; i++) {
            _hasClaimTopic[address(trustedIssuer)][claimTopics[i]] = true;
        }

        emit TrustedIssuerAdded(trustedIssuer, claimTopics);
    }

    function removeTrustedIssuer(
        IClaimIssuer trustedIssuer
    ) external override onlyOwner {
        require(_isTrustedIssuer[address(trustedIssuer)], "not trusted");

        // Remove claim topic mappings
        uint256[] memory topics = _issuerClaimTopics[address(trustedIssuer)];
        for (uint256 i = 0; i < topics.length; i++) {
            delete _hasClaimTopic[address(trustedIssuer)][topics[i]];
        }
        delete _issuerClaimTopics[address(trustedIssuer)];
        _isTrustedIssuer[address(trustedIssuer)] = false;

        // Remove from array
        uint256 length = _trustedIssuers.length;
        for (uint256 i = 0; i < length; i++) {
            if (_trustedIssuers[i] == trustedIssuer) {
                _trustedIssuers[i] = _trustedIssuers[length - 1];
                _trustedIssuers.pop();
                break;
            }
        }

        emit TrustedIssuerRemoved(trustedIssuer);
    }

    function updateIssuerClaimTopics(
        IClaimIssuer trustedIssuer,
        uint256[] calldata claimTopics
    ) external override onlyOwner {
        require(_isTrustedIssuer[address(trustedIssuer)], "not trusted");
        require(claimTopics.length > 0, "no claim topics");

        // Remove old topic mappings
        uint256[] memory oldTopics = _issuerClaimTopics[address(trustedIssuer)];
        for (uint256 i = 0; i < oldTopics.length; i++) {
            delete _hasClaimTopic[address(trustedIssuer)][oldTopics[i]];
        }

        // Set new topics
        _issuerClaimTopics[address(trustedIssuer)] = claimTopics;
        for (uint256 i = 0; i < claimTopics.length; i++) {
            _hasClaimTopic[address(trustedIssuer)][claimTopics[i]] = true;
        }

        emit ClaimTopicsUpdated(trustedIssuer, claimTopics);
    }

    function getTrustedIssuers()
        external
        view
        override
        returns (IClaimIssuer[] memory)
    {
        return _trustedIssuers;
    }

    function isTrustedIssuer(address issuer) external view override returns (bool) {
        return _isTrustedIssuer[issuer];
    }

    function getTrustedIssuerClaimTopics(
        IClaimIssuer trustedIssuer
    ) external view override returns (uint256[] memory) {
        return _issuerClaimTopics[address(trustedIssuer)];
    }

    function hasClaimTopic(
        address issuer,
        uint256 claimTopic
    ) external view override returns (bool) {
        return _hasClaimTopic[issuer][claimTopic];
    }
}

src/sale/Sale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../interfaces/IIdentityRegistry.sol";
import "../fraction/CiretaFractionToken.sol";
import "../vault/CiretaVault.sol";
import "../otc/IssuerOTCToken.sol";

/// @title Sale
/// @notice Multi-phase token sale with soft/hard cap, platform fee, OTC allocation, and refunds.
///         Admin is resolved dynamically from factory.owner() — single source of truth.
///         - admin: whoever owns the CiretaSaleFactory at call time (platform admin / multisig)
///         - factory: the CiretaSaleFactory that deployed this sale (also treated as admin for deploy-time setup)
///         - issuer: token issuer — day-to-day sale operations, fund withdrawal
contract Sale is Initializable, UUPSUpgradeable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum SaleStatus { Draft, Active, Paused, FinalizedSuccess, FinalizedFailed, Rejected }
    enum SaleMode { Direct, Vested }
    enum SaleStructure { PhaseAllocated, PriceTiered }

    struct Phase {
        string name;
        uint256 pricePerToken;
        uint256 allocation;
        uint256 sold;
        uint256 minContribution;
        uint256 maxContribution;
        uint256 startTime;
        uint256 endTime;
        bool whitelistOnly;
    }

    struct Contribution {
        uint256 amount;           // USDC contributed on-platform
        uint256 tokensAllocated;  // Tokens to receive
        bool claimed;
        bool refunded;
        bool isOtc;               // True = off-platform OTC allocation
    }

    // ── State ────────────────────────────────────────────────────────────────
    address public token;
    IERC20 public paymentToken;
    IIdentityRegistry public identityRegistry;
    address public issuer;
    address public factory;     // CiretaSaleFactory — admin resolved via factory.owner()
    address public feeManager;

    uint256 public softCap;
    uint256 public hardCap;
    uint256 public feeBasisPoints;   // e.g. 250 = 2.5%
    uint256 public feeCapUsdc;       // Absolute max fee in USDC (6 decimals)

    uint256 public totalRaised;              // Total USDC raised (on-platform only)
    uint256 public totalOtcAllocated;        // Total OTC token allocation (excluded from fee)
    uint256 public platformFeeCollected;

    SaleStatus public status;
    Phase[] public phases;

    mapping(uint256 => mapping(address => bool)) public whitelisted;
    mapping(address => Contribution) public contributions;
    mapping(address => uint256) public totalContributed;
    mapping(address => uint256) public otcAllocations;

    /// @notice Per-block contribution limit to mitigate front-running attacks.
    uint256 public maxPerBlock;
    mapping(uint256 => uint256) private _blockContributions;

    // ── Vested mode state ─────────────────────────────────────────────────────
    SaleMode public saleMode;
    CiretaVault public vault;
    CiretaFractionToken public fractionToken;

    // ── OTC token state ──────────────────────────────────────────────────────
    IssuerOTCToken public otcToken;

    // ── Sale structure ──────────────────────────────────────────────────────
    SaleStructure public saleStructure;

    // ── Emergency withdrawal ────────────────────────────────────────────────
    uint256 public finalizedAt;
    uint256 public constant EMERGENCY_WITHDRAW_DELAY = 90 days;

    /// @dev Reserved storage gap for future upgrades
    uint256[46] private __gap;

    // ── Events ───────────────────────────────────────────────────────────────
    event PhaseAdded(uint256 indexed phaseId, string name, uint256 pricePerToken);
    event Purchase(address indexed buyer, uint256 indexed phaseId, uint256 amount, uint256 tokensAllocated, bool isOTC);
    event OTCAllocation(address indexed investor, uint256 tokensAllocated, string paymentReference);
    event TokensClaimed(address indexed claimer, uint256 amount);
    event RefundClaimed(address indexed contributor, uint256 amount);
    event SaleFinalized(bool success, uint256 totalRaised, uint256 platformFee);
    event SaleStatusChanged(SaleStatus newStatus);
    event MaxPerBlockUpdated(uint256 newMax);
    event WhitelistUpdated(uint256 indexed phaseId, uint256 count, bool allow);
    event EmergencyWithdraw(address indexed recipient, uint256 amount);
    event ProjectTokensDeposited(uint256 amount);
    event FundsWithdrawn(address indexed recipient, uint256 amount);
    event TokensWithdrawn(address indexed recipient, uint256 amount);

    // ── Errors ───────────────────────────────────────────────────────────────
    error InvalidStatus();
    error NotAdmin();
    error NotIssuer();
    error NotIssuerOrAdmin();
    error ZeroAddress();
    error NothingToClaim();
    error AlreadyClaimed();
    error UseVaultClaim();
    error InvalidPhase();
    error PhaseNotStarted();
    error PhaseEnded();
    error BelowMinContribution();
    error ExceedsMaxContribution();
    error ExceedsHardCap();
    error ExceedsBlockLimit();
    error KYCRequired();
    error NotWhitelisted();
    error ExceedsAllocation();
    error CannotAddPhase();
    error ZeroMaxPerBlock();
    error SaleNotActive();
    error InvestorNotVerified();
    error CannotFinalize();
    error OTCNotEnabled();
    error NothingToWithdraw();
    error SaleNotFinalized();
    error TokensNotDeposited();
    error DelayNotElapsed();

    // ── Access Control ──────────────────────────────────────────────────────

    /// @dev Returns the current platform admin (factory's owner). Single source of truth.
    function admin() public view returns (address) {
        return OwnableUpgradeable(factory).owner();
    }

    /// @dev Is the caller the platform admin or the factory itself?
    function _isAdmin() internal view returns (bool) {
        return msg.sender == factory || msg.sender == OwnableUpgradeable(factory).owner();
    }

    modifier adminOnly() {
        if (!_isAdmin()) revert NotAdmin();
        _;
    }

    modifier onlyIssuer() {
        if (msg.sender != issuer) revert NotIssuer();
        _;
    }

    modifier onlyIssuerOrAdmin() {
        if (msg.sender != issuer && !_isAdmin()) revert NotIssuerOrAdmin();
        _;
    }

    modifier onlyStatus(SaleStatus s) {
        if (status != s) revert InvalidStatus();
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(
        address _token,
        address _paymentToken,
        address _identityRegistry,
        address _issuer,
        address _factory,
        address _feeManager,
        uint256 _softCap,
        uint256 _hardCap,
        uint256 _feeBasisPoints,
        uint256 _feeCapUsdc,
        address _otcToken
    ) external initializer {
        if (_token == address(0)) revert ZeroAddress();
        if (_paymentToken == address(0)) revert ZeroAddress();
        if (_identityRegistry == address(0)) revert ZeroAddress();
        if (_issuer == address(0)) revert ZeroAddress();
        if (_factory == address(0)) revert ZeroAddress();
        if (_feeManager == address(0)) revert ZeroAddress();

        token = _token;
        paymentToken = IERC20(_paymentToken);
        identityRegistry = IIdentityRegistry(_identityRegistry);
        issuer = _issuer;
        factory = _factory;
        feeManager = _feeManager;
        softCap = _softCap;
        hardCap = _hardCap;
        feeBasisPoints = _feeBasisPoints;
        feeCapUsdc = _feeCapUsdc;
        if (_otcToken != address(0)) otcToken = IssuerOTCToken(_otcToken);
        maxPerBlock = 50_000 * 1e6; // 50,000 USDC default per-block cap
        status = SaleStatus.Draft;
    }

    function _authorizeUpgrade(address) internal override adminOnly {}

    // ── Admin-Only Functions ────────────────────────────────────────────────

    /// @notice Activate the sale (Draft → Active). Admin approval gate.
    function activate() external adminOnly onlyStatus(SaleStatus.Draft) {
        // Require project tokens deposited before activation
        if (saleMode == SaleMode.Direct) {
            // Direct: tokens must be in the sale contract
            uint256 tokenBalance = IERC20(token).balanceOf(address(this));
            if (tokenBalance == 0) revert TokensNotDeposited();
        } else {
            // Vested: tokens must be in the vault
            uint256 vaultBalance = IERC20(token).balanceOf(address(vault));
            if (vaultBalance == 0) revert TokensNotDeposited();
        }
        // Require at least one phase configured
        if (phases.length == 0) revert InvalidStatus();

        status = SaleStatus.Active;
        emit SaleStatusChanged(SaleStatus.Active);
    }

    /// @notice Reject the sale permanently (Draft → Rejected). Admin blocks activation forever.
    /// Issuer can still withdraw deposited project tokens via withdrawTokens().
    function reject() external adminOnly onlyStatus(SaleStatus.Draft) {
        status = SaleStatus.Rejected;
        emit SaleStatusChanged(SaleStatus.Rejected);
    }

    /// @notice Withdraw project tokens from a draft or rejected sale. Issuer reclaims tokens.
    function withdrawTokens() external onlyIssuer nonReentrant {
        if (status != SaleStatus.Draft && status != SaleStatus.Rejected) revert InvalidStatus();
        uint256 balance = IERC20(token).balanceOf(address(this));
        if (balance == 0) revert NothingToWithdraw();
        IERC20(token).safeTransfer(issuer, balance);
        emit TokensWithdrawn(issuer, balance);
    }

    /// @notice Unpause the sale. Only admin can lift a regulatory hold.
    function unpause() external adminOnly onlyStatus(SaleStatus.Paused) {
        status = SaleStatus.Active;
        emit SaleStatusChanged(SaleStatus.Active);
    }

    /// @notice Configure vested mode. Must be called before activation.
    function setVestedMode(address _vault, address _fractionToken) external adminOnly onlyStatus(SaleStatus.Draft) {
        if (_vault == address(0) || _fractionToken == address(0)) revert ZeroAddress();
        saleMode = SaleMode.Vested;
        vault = CiretaVault(_vault);
        fractionToken = CiretaFractionToken(_fractionToken);
    }

    // ── Issuer-Only Functions ───────────────────────────────────────────────

    /// @notice Add a sale phase. Only issuer configures their own sale.
    function addPhase(
        string calldata name,
        uint256 pricePerToken,
        uint256 allocation,
        uint256 minContribution,
        uint256 maxContribution,
        uint256 startTime,
        uint256 endTime,
        bool whitelistOnly
    ) external onlyIssuer {
        if (status != SaleStatus.Draft && status != SaleStatus.Active) revert CannotAddPhase();
        phases.push(Phase({
            name: name,
            pricePerToken: pricePerToken,
            allocation: allocation,
            sold: 0,
            minContribution: minContribution,
            maxContribution: maxContribution,
            startTime: startTime,
            endTime: endTime,
            whitelistOnly: whitelistOnly
        }));
        emit PhaseAdded(phases.length - 1, name, pricePerToken);
    }

    /// @notice Manage investor whitelist per phase. Only issuer.
    function setWhitelist(uint256 phaseId, address[] calldata addresses, bool allow) external onlyIssuer {
        if (status == SaleStatus.Rejected) revert InvalidStatus();
        for (uint256 i = 0; i < addresses.length; i++) {
            whitelisted[phaseId][addresses[i]] = allow;
        }
        emit WhitelistUpdated(phaseId, addresses.length, allow);
    }

    /// @notice Set per-block contribution limit. Only issuer.
    function setMaxPerBlock(uint256 _maxPerBlock) external onlyIssuer {
        if (status == SaleStatus.Rejected) revert InvalidStatus();
        if (_maxPerBlock == 0) revert ZeroMaxPerBlock();
        maxPerBlock = _maxPerBlock;
        emit MaxPerBlockUpdated(_maxPerBlock);
    }

    /// @notice Set or update the OTC token address. Only issuer.
    function setOTCToken(address _otcToken) external onlyIssuer {
        if (status == SaleStatus.Rejected) revert InvalidStatus();
        otcToken = IssuerOTCToken(_otcToken);
    }

    /// @notice Set the sale structure. Only issuer, only in Draft status.
    function setSaleStructure(SaleStructure _structure) external onlyIssuer onlyStatus(SaleStatus.Draft) {
        saleStructure = _structure;
    }

    /// @notice Issuer allocates tokens to investor who paid off-platform (OTC).
    function issuerAllocate(
        address investor,
        uint256 tokenAmount,
        string calldata paymentReference
    ) external onlyIssuer {
        if (status != SaleStatus.Active && status != SaleStatus.Draft) revert SaleNotActive();
        if (!identityRegistry.isVerified(investor)) revert InvestorNotVerified();

        contributions[investor].tokensAllocated += tokenAmount;
        otcAllocations[investor] += tokenAmount;
        totalOtcAllocated += tokenAmount;

        emit OTCAllocation(investor, tokenAmount, paymentReference);
    }

    /// @notice Deposit project tokens into the vault for vested mode. Only issuer.
    function depositProjectTokens(uint256 amount) external onlyIssuer nonReentrant {
        if (status == SaleStatus.Rejected) revert InvalidStatus();
        if (saleMode != SaleMode.Vested) revert InvalidStatus();
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        IERC20(token).approve(address(vault), amount);
        vault.depositTokens(amount);
        emit ProjectTokensDeposited(amount);
    }

    /// @notice Withdraw raised USDC to issuer wallet. Only issuer — admin cannot touch.
    function withdrawFunds() external onlyIssuer nonReentrant {
        if (status != SaleStatus.FinalizedSuccess) revert SaleNotFinalized();

        uint256 balance = paymentToken.balanceOf(address(this));
        if (balance == 0) revert NothingToWithdraw();

        paymentToken.safeTransfer(issuer, balance);
        emit FundsWithdrawn(issuer, balance);
    }

    // ── Dual Authority (Issuer or Admin) ────────────────────────────────────

    /// @notice Pause the sale. Both issuer and admin can emergency-pause.
    function pause() external onlyIssuerOrAdmin onlyStatus(SaleStatus.Active) {
        status = SaleStatus.Paused;
        emit SaleStatusChanged(SaleStatus.Paused);
    }

    /// @notice Finalize the sale. Issuer finalizes normally; admin override for abandoned sales.
    function finalizeSale() external onlyIssuerOrAdmin nonReentrant {
        if (status != SaleStatus.Active && status != SaleStatus.Paused) revert CannotFinalize();
        _finalize();
    }

    // ── Emergency Withdrawal ────────────────────────────────────────────────

    /// @notice Emergency withdrawal for admin when issuer disappears.
    ///         Only callable 30 days after successful finalization.
    function emergencyWithdraw(address recipient) external adminOnly nonReentrant {
        if (status != SaleStatus.FinalizedSuccess) revert SaleNotFinalized();
        if (block.timestamp < finalizedAt + EMERGENCY_WITHDRAW_DELAY) revert DelayNotElapsed();
        if (recipient == address(0)) revert ZeroAddress();

        uint256 remaining = paymentToken.balanceOf(address(this));
        if (remaining == 0) revert NothingToWithdraw();

        paymentToken.safeTransfer(recipient, remaining);
        emit EmergencyWithdraw(recipient, remaining);
    }

    // ── Buy ─────────────────────────────────────────────────────────────────

    function buy(uint256 phaseId, uint256 amount) external nonReentrant onlyStatus(SaleStatus.Active) {
        // ── Checks ──
        if (phaseId >= phases.length) revert InvalidPhase();
        Phase storage phase = phases[phaseId];
        if (block.timestamp < phase.startTime) revert PhaseNotStarted();
        if (block.timestamp > phase.endTime) revert PhaseEnded();
        if (totalContributed[msg.sender] == 0 && amount < phase.minContribution) revert BelowMinContribution();
        if (phase.maxContribution > 0 && totalContributed[msg.sender] + amount > phase.maxContribution) revert ExceedsMaxContribution();
        if (totalRaised + amount > hardCap) revert ExceedsHardCap();
        if (_blockContributions[block.number] + amount > maxPerBlock) revert ExceedsBlockLimit();
        if (!identityRegistry.isVerified(msg.sender)) revert KYCRequired();
        if (phase.whitelistOnly && !whitelisted[phaseId][msg.sender]) revert NotWhitelisted();

        uint256 tokensToAllocate = (amount * 1e18) / phase.pricePerToken;
        if (saleStructure == SaleStructure.PhaseAllocated) {
            if (phase.sold + tokensToAllocate > phase.allocation) revert ExceedsAllocation();
        }

        // ── Effects ──
        phase.sold += tokensToAllocate;
        totalRaised += amount;
        totalContributed[msg.sender] += amount;
        _blockContributions[block.number] += amount;
        contributions[msg.sender].amount += amount;
        contributions[msg.sender].tokensAllocated += tokensToAllocate;

        // ── Interactions (CEI) ──
        paymentToken.safeTransferFrom(msg.sender, address(this), amount);

        if (saleMode == SaleMode.Direct) {
            IERC20(token).safeTransfer(msg.sender, tokensToAllocate);
            contributions[msg.sender].claimed = true;
        } else {
            fractionToken.mint(msg.sender, tokensToAllocate);
            vault.recordAllocation(msg.sender, tokensToAllocate);
        }

        if (totalRaised >= hardCap) {
            _finalize();
        }

        emit Purchase(msg.sender, phaseId, amount, tokensToAllocate, false);
    }

    // ── OTC Token Purchase ──────────────────────────────────────────────────

    function buyOTC(uint256 phaseId, uint256 amount) external nonReentrant onlyStatus(SaleStatus.Active) {
        // ── Checks ──
        if (address(otcToken) == address(0)) revert OTCNotEnabled();
        require(amount > 0, "amount must be > 0");

        if (phaseId >= phases.length) revert InvalidPhase();
        Phase storage phase = phases[phaseId];
        if (block.timestamp < phase.startTime) revert PhaseNotStarted();
        if (block.timestamp > phase.endTime) revert PhaseEnded();
        if (totalContributed[msg.sender] == 0 && amount < phase.minContribution) revert BelowMinContribution();
        if (phase.maxContribution > 0 && totalContributed[msg.sender] + amount > phase.maxContribution) revert ExceedsMaxContribution();
        if (totalRaised + amount > hardCap) revert ExceedsHardCap();
        if (_blockContributions[block.number] + amount > maxPerBlock) revert ExceedsBlockLimit();
        if (!identityRegistry.isVerified(msg.sender)) revert KYCRequired();
        if (phase.whitelistOnly && !whitelisted[phaseId][msg.sender]) revert NotWhitelisted();

        // Verify buyer has sufficient OTC token balance and approval
        require(IERC20(address(otcToken)).balanceOf(msg.sender) >= amount, "insufficient OTC token balance");
        require(IERC20(address(otcToken)).allowance(msg.sender, address(this)) >= amount, "OTC token not approved");

        uint256 tokensToAllocate = (amount * 1e18) / phase.pricePerToken;
        require(tokensToAllocate > 0, "amount too small for token allocation");
        if (saleStructure == SaleStructure.PhaseAllocated) {
            if (phase.sold + tokensToAllocate > phase.allocation) revert ExceedsAllocation();
        }

        // ── Effects ──
        phase.sold += tokensToAllocate;
        totalRaised += amount; // OTC counts toward hard cap
        totalOtcAllocated += tokensToAllocate;
        totalContributed[msg.sender] += amount;
        _blockContributions[block.number] += amount;
        contributions[msg.sender].amount += amount;
        contributions[msg.sender].tokensAllocated += tokensToAllocate;
        contributions[msg.sender].isOtc = true;
        otcAllocations[msg.sender] += tokensToAllocate;

        // ── Interactions (CEI) ──
        IERC20(address(otcToken)).safeTransferFrom(msg.sender, address(this), amount);
        otcToken.burn(address(this), amount);

        if (saleMode == SaleMode.Direct) {
            IERC20(token).safeTransfer(msg.sender, tokensToAllocate);
            contributions[msg.sender].claimed = true;
        } else {
            fractionToken.mint(msg.sender, tokensToAllocate);
            vault.recordAllocation(msg.sender, tokensToAllocate);
        }

        emit Purchase(msg.sender, phaseId, amount, tokensToAllocate, true);
    }

    // ── Finalization (internal) ─────────────────────────────────────────────

    function _finalize() internal {
        if (totalRaised >= softCap) {
            status = SaleStatus.FinalizedSuccess;
            finalizedAt = block.timestamp;

            uint256 fee = 0;
            if (feeManager != address(0) && feeBasisPoints > 0) {
                fee = (totalRaised * feeBasisPoints) / 10000;
                if (feeCapUsdc > 0 && fee > feeCapUsdc) fee = feeCapUsdc;
                platformFeeCollected = fee;
                paymentToken.safeTransfer(feeManager, fee);
            }

            if (saleMode == SaleMode.Vested) {
                vault.startVesting();
            }

            emit SaleFinalized(true, totalRaised, fee);
        } else {
            status = SaleStatus.FinalizedFailed;
            finalizedAt = block.timestamp;
            emit SaleFinalized(false, totalRaised, 0);
        }
        emit SaleStatusChanged(status);
    }

    // ── Claims & Refunds ─────────────────────────────────────────────────────

    function claimTokens() external nonReentrant {
        if (saleMode == SaleMode.Vested) revert UseVaultClaim();
        if (status != SaleStatus.FinalizedSuccess) revert InvalidStatus();
        Contribution storage contrib = contributions[msg.sender];
        if (contrib.tokensAllocated == 0) revert NothingToClaim();
        if (contrib.claimed) revert AlreadyClaimed();

        contrib.claimed = true;
        IERC20(token).safeTransfer(msg.sender, contrib.tokensAllocated);
        emit TokensClaimed(msg.sender, contrib.tokensAllocated);
    }

    function claimRefund() external nonReentrant {
        if (status != SaleStatus.FinalizedFailed) revert InvalidStatus();
        Contribution storage contrib = contributions[msg.sender];
        if (contrib.amount == 0) revert NothingToClaim();
        if (contrib.refunded) revert AlreadyClaimed();

        contrib.refunded = true;

        if (saleMode == SaleMode.Vested) {
            uint256 fractionBalance = fractionToken.balanceOf(msg.sender);
            if (fractionBalance > 0) {
                fractionToken.burnFrom(msg.sender, fractionBalance);
            }
        }

        uint256 refundAmount = contrib.amount;
        paymentToken.safeTransfer(msg.sender, refundAmount);
        emit RefundClaimed(msg.sender, refundAmount);
    }

    // ── View ─────────────────────────────────────────────────────────────────

    function getPhaseCount() external view returns (uint256) { return phases.length; }
    function getPhase(uint256 phaseId) external view returns (Phase memory) { return phases[phaseId]; }
    function getContribution(address contributor) external view returns (Contribution memory) { return contributions[contributor]; }
    function getTotalRaised() external view returns (uint256) { return totalRaised; }

    function getCurrentPhase() external view returns (uint256) {
        for (uint256 i = 0; i < phases.length; i++) {
            if (block.timestamp >= phases[i].startTime && block.timestamp <= phases[i].endTime) {
                return i;
            }
        }
        return type(uint256).max;
    }

    function calculateFee(uint256 onPlatformRaised) external view returns (uint256) {
        if (feeBasisPoints == 0) return 0;
        uint256 fee = (onPlatformRaised * feeBasisPoints) / 10000;
        if (feeCapUsdc > 0 && fee > feeCapUsdc) return feeCapUsdc;
        return fee;
    }
}

src/token/CiretaToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20BurnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "../interfaces/IToken.sol";
import "../interfaces/IIdentityRegistry.sol";
import "../interfaces/ICompliance.sol";

/**
 * @title CiretaToken
 * @dev ERC-3643 compliant security token for Cireta platform
 */
contract CiretaToken is
    Initializable,
    ERC20Upgradeable,
    ERC20BurnableUpgradeable,
    ERC20PausableUpgradeable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    bytes32 public constant AGENT_ROLE = keccak256("AGENT_ROLE");
    bytes32 public constant SUPPLY_ROLE = keccak256("SUPPLY_ROLE");
    bytes32 public constant FREEZE_ROLE = keccak256("FREEZE_ROLE");
    bytes32 public constant RECOVERY_ROLE = keccak256("RECOVERY_ROLE");

    // Identity registry for investor verification
    IIdentityRegistry private _identityRegistry;

    // Compliance contract for transfer rules
    ICompliance private _compliance;

    // Token decimals
    uint8 private _decimals;

    // Token onchain ID
    address private _onchainID;

    // Frozen addresses
    mapping(address => bool) private _frozen;

    // Partially frozen tokens per address
    mapping(address => uint256) private _frozenTokens;

    // Flag to bypass _update validation during forced operations (transfer/recovery)
    bool private _forcedOperation;

    // Custom name/symbol overrides (ERC20Upgradeable doesn't support post-init changes)
    string private _nameOverride;
    string private _symbolOverride;

    /// @dev Reserved storage gap for future upgrades
    uint256[50] private __gap;

    // Events from IToken
    event UpdatedTokenInformation(
        string indexed newName,
        string indexed newSymbol,
        uint8 newDecimals,
        string newVersion,
        address indexed newOnchainID
    );
    event IdentityRegistryAdded(address indexed identityRegistry);
    event ComplianceAdded(address indexed compliance);
    event RecoverySuccess(
        address indexed lostWallet,
        address indexed newWallet,
        address indexed investorOnchainID
    );
    event AddressFrozen(address indexed addr, bool indexed isFrozen, address indexed agent);
    event TokensFrozen(address indexed addr, uint256 amount);
    event TokensUnfrozen(address indexed addr, uint256 amount);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        address identityRegistry_,
        address compliance_,
        address owner_,
        address admin_
    ) public initializer {
        __ERC20_init(name_, symbol_);
        __ERC20Burnable_init();
        __ERC20Pausable_init();
        __AccessControl_init();

        require(decimals_ <= 6, "CiretaToken: max 6 decimals");
        _decimals = decimals_;
        _identityRegistry = IIdentityRegistry(identityRegistry_);
        _compliance = ICompliance(compliance_);

        // Issuer (owner_) gets all roles
        _grantRole(DEFAULT_ADMIN_ROLE, owner_);
        _grantRole(AGENT_ROLE, owner_);
        _grantRole(SUPPLY_ROLE, owner_);
        _grantRole(FREEZE_ROLE, owner_);
        _grantRole(RECOVERY_ROLE, owner_);

        // Platform admin gets oversight roles (NOT SUPPLY_ROLE —
        // admin must never mint/burn an issuer's security tokens)
        if (admin_ != address(0) && admin_ != owner_) {
            _grantRole(DEFAULT_ADMIN_ROLE, admin_);
            _grantRole(AGENT_ROLE, admin_);
            _grantRole(FREEZE_ROLE, admin_);
            _grantRole(RECOVERY_ROLE, admin_);
        }
    }

    function _authorizeUpgrade(address newImplementation)
        internal
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {}

    function decimals() public view virtual override returns (uint8) {
        return _decimals;
    }

    function name() public view virtual override returns (string memory) {
        return bytes(_nameOverride).length > 0 ? _nameOverride : super.name();
    }

    function symbol() public view virtual override returns (string memory) {
        return bytes(_symbolOverride).length > 0 ? _symbolOverride : super.symbol();
    }

    // ============ Identity & Compliance ============

    function setIdentityRegistry(
        address identityRegistry_
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(identityRegistry_ != address(0), "zero address");
        _identityRegistry = IIdentityRegistry(identityRegistry_);
        emit IdentityRegistryAdded(identityRegistry_);
    }

    function setCompliance(
        address compliance_
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(compliance_ != address(0), "zero address");
        _compliance = ICompliance(compliance_);
        emit ComplianceAdded(compliance_);
    }

    function identityRegistry() external view returns (IIdentityRegistry) {
        return _identityRegistry;
    }

    function compliance() external view returns (ICompliance) {
        return _compliance;
    }

    // ============ Token Info ============

    function setName(string calldata newName) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _nameOverride = newName;
        emit UpdatedTokenInformation(newName, symbol(), _decimals, "1.0", _onchainID);
    }

    function setSymbol(string calldata newSymbol) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _symbolOverride = newSymbol;
        emit UpdatedTokenInformation(name(), newSymbol, _decimals, "1.0", _onchainID);
    }

    function setOnchainID(address onchainID_) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _onchainID = onchainID_;
        emit UpdatedTokenInformation(name(), symbol(), _decimals, "1.0", onchainID_);
    }

    // ============ Pause/Unpause ============

    function pause() external onlyRole(AGENT_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(AGENT_ROLE) {
        _unpause();
    }

    // ============ Freeze ============

    function setAddressFrozen(
        address addr,
        bool freeze
    ) external onlyRole(FREEZE_ROLE) {
        require(addr != address(0), "zero address");
        _frozen[addr] = freeze;
        emit AddressFrozen(addr, freeze, msg.sender);
    }

    function freezePartialTokens(
        address addr,
        uint256 amount
    ) external onlyRole(FREEZE_ROLE) {
        require(amount <= balanceOf(addr) - _frozenTokens[addr], "not enough tokens");
        _frozenTokens[addr] += amount;
        emit TokensFrozen(addr, amount);
    }

    function unfreezePartialTokens(
        address addr,
        uint256 amount
    ) external onlyRole(FREEZE_ROLE) {
        require(amount <= _frozenTokens[addr], "not enough frozen");
        _frozenTokens[addr] -= amount;
        emit TokensUnfrozen(addr, amount);
    }

    function isFrozen(address addr) external view returns (bool) {
        return _frozen[addr];
    }

    function getFrozenTokens(address addr) external view returns (uint256) {
        return _frozenTokens[addr];
    }

    // ============ Batch Freeze ============

    function batchSetAddressFrozen(
        address[] calldata addrList,
        bool[] calldata freezeList
    ) external onlyRole(FREEZE_ROLE) {
        require(addrList.length == freezeList.length, "length mismatch");
        for (uint256 i = 0; i < addrList.length; i++) {
            _frozen[addrList[i]] = freezeList[i];
            emit AddressFrozen(addrList[i], freezeList[i], msg.sender);
        }
    }

    function batchFreezePartialTokens(
        address[] calldata addrList,
        uint256[] calldata amounts
    ) external onlyRole(FREEZE_ROLE) {
        require(addrList.length == amounts.length, "length mismatch");
        for (uint256 i = 0; i < addrList.length; i++) {
            require(
                amounts[i] <= balanceOf(addrList[i]) - _frozenTokens[addrList[i]],
                "not enough tokens"
            );
            _frozenTokens[addrList[i]] += amounts[i];
            emit TokensFrozen(addrList[i], amounts[i]);
        }
    }

    function batchUnfreezePartialTokens(
        address[] calldata addrList,
        uint256[] calldata amounts
    ) external onlyRole(FREEZE_ROLE) {
        require(addrList.length == amounts.length, "length mismatch");
        for (uint256 i = 0; i < addrList.length; i++) {
            require(amounts[i] <= _frozenTokens[addrList[i]], "not enough frozen");
            _frozenTokens[addrList[i]] -= amounts[i];
            emit TokensUnfrozen(addrList[i], amounts[i]);
        }
    }

    // ============ Mint/Burn ============

    /// @notice Mint tokens. SUPPLY_ROLE is already trusted — skip identity check
    /// since minting is an admin/issuer operation, not a transfer.
    function mint(address to, uint256 amount) external onlyRole(SUPPLY_ROLE) {
        _mint(to, amount);
        _compliance.created(to, amount);
    }

    function burn(address account, uint256 amount) external onlyRole(SUPPLY_ROLE) {
        _burn(account, amount);
        _compliance.destroyed(account, amount);
    }

    function batchMint(
        address[] calldata toList,
        uint256[] calldata amounts
    ) external onlyRole(SUPPLY_ROLE) {
        require(toList.length == amounts.length, "length mismatch");
        for (uint256 i = 0; i < toList.length; i++) {
            require(_identityRegistry.isVerified(toList[i]), "identity not verified");
            _mint(toList[i], amounts[i]);
            _compliance.created(toList[i], amounts[i]);
        }
    }

    function batchBurn(
        address[] calldata fromList,
        uint256[] calldata amounts
    ) external onlyRole(SUPPLY_ROLE) {
        require(fromList.length == amounts.length, "length mismatch");
        for (uint256 i = 0; i < fromList.length; i++) {
            _burn(fromList[i], amounts[i]);
            _compliance.destroyed(fromList[i], amounts[i]);
        }
    }

    // ============ Forced Transfer ============

    function forcedTransfer(
        address from,
        address to,
        uint256 amount
    ) external onlyRole(AGENT_ROLE) returns (bool) {
        require(_identityRegistry.isVerified(to), "to identity not verified");

        // Unfreeze tokens if needed
        if (_frozenTokens[from] > 0) {
            uint256 unfreezeAmount = amount > _frozenTokens[from]
                ? _frozenTokens[from]
                : amount;
            _frozenTokens[from] -= unfreezeAmount;
            emit TokensUnfrozen(from, unfreezeAmount);
        }

        // Bypass _update validation (frozen checks, compliance canTransfer)
        // but still notify compliance modules via transferred() for holder tracking
        _forcedOperation = true;
        _transfer(from, to, amount);
        _forcedOperation = false;
        return true;
    }

    function batchForcedTransfer(
        address[] calldata fromList,
        address[] calldata toList,
        uint256[] calldata amounts
    ) external onlyRole(AGENT_ROLE) {
        require(fromList.length == toList.length, "length mismatch");
        require(fromList.length == amounts.length, "length mismatch");

        _forcedOperation = true;
        for (uint256 i = 0; i < fromList.length; i++) {
            require(_identityRegistry.isVerified(toList[i]), "to identity not verified");

            if (_frozenTokens[fromList[i]] > 0) {
                uint256 unfreezeAmount = amounts[i] > _frozenTokens[fromList[i]]
                    ? _frozenTokens[fromList[i]]
                    : amounts[i];
                _frozenTokens[fromList[i]] -= unfreezeAmount;
                emit TokensUnfrozen(fromList[i], unfreezeAmount);
            }

            _transfer(fromList[i], toList[i], amounts[i]);
        }
        _forcedOperation = false;
    }

    // ============ Recovery ============

    function recoveryAddress(
        address lostWallet,
        address newWallet,
        address investorOnchainID
    ) external onlyRole(RECOVERY_ROLE) returns (bool) {
        require(_identityRegistry.isVerified(newWallet), "new wallet not verified");
        require(
            address(_identityRegistry.identity(lostWallet)) == investorOnchainID,
            "identity mismatch"
        );

        uint256 balance = balanceOf(lostWallet);
        if (balance > 0) {
            // Bypass _update validation — lost wallet may be frozen.
            // _update() already calls compliance.transferred() once for holder tracking.
            _forcedOperation = true;
            _transfer(lostWallet, newWallet, balance);
            _forcedOperation = false;
        }

        // Transfer frozen tokens count
        if (_frozenTokens[lostWallet] > 0) {
            _frozenTokens[newWallet] = _frozenTokens[lostWallet];
            delete _frozenTokens[lostWallet];
        }

        // Transfer frozen status
        if (_frozen[lostWallet]) {
            _frozen[newWallet] = true;
            delete _frozen[lostWallet];
        }

        emit RecoverySuccess(lostWallet, newWallet, investorOnchainID);
        return true;
    }

    // ============ Batch Transfer ============

    function batchTransfer(
        address[] calldata toList,
        uint256[] calldata amounts
    ) external {
        require(toList.length == amounts.length, "length mismatch");
        for (uint256 i = 0; i < toList.length; i++) {
            transfer(toList[i], amounts[i]);
        }
    }

    // ============ Transfer Validation ============

    function _update(
        address from,
        address to,
        uint256 value
    ) internal virtual override(ERC20Upgradeable, ERC20PausableUpgradeable) {
        // Skip validation for mint/burn and forced operations (forcedTransfer, recovery)
        if (from != address(0) && to != address(0) && !_forcedOperation) {
            require(!_frozen[from], "sender frozen");
            require(!_frozen[to], "recipient frozen");
            require(
                balanceOf(from) - _frozenTokens[from] >= value,
                "insufficient unfrozen balance"
            );
            require(_identityRegistry.isVerified(to), "recipient not verified");
            require(_compliance.canTransfer(from, to, value), "transfer not compliant");
        }

        super._update(from, to, value);

        // Always notify compliance of transfers (including forced) for holder tracking
        if (from != address(0) && to != address(0)) {
            _compliance.transferred(from, to, value);
        }
    }
}

